NativeSignal grp0_load_bitmap(VM& vm, Thread& thread) {
    const uint32_t resource_address = thread.stack.pop();
    const uint32_t archive_address = thread.stack.pop();
    const uint32_t type = thread.stack.pop();
    const std::string archive =
        archive_address == 0
            ? std::string()
            : vm.memory().read_cstring(archive_address, thread.base);
    const std::string resource =
        resource_address == 0
            ? std::string()
            : vm.memory().read_cstring(resource_address, thread.base);
    try {
        const bool loaded = vm.load_bitmap_resource(type, archive, resource);
        if (debug_trace(DebugTrace::Display)) {
            std::cout << "BITMAP_LOAD_RESULT id=" << type << " loaded=" << loaded
                      << " source=" << archive << ':' << resource;
            if (const auto surface = vm.graphics_surfaces().find(type);
                surface != vm.graphics_surfaces().end()) {
                std::cout << " size=" << surface->second.width << ',' << surface->second.height
                          << " format=" << surface->second.format;
            }
            if (const auto error = vm.bitmap_load_errors().find(type); error != vm.bitmap_load_errors().end())
                std::cout << " error=" << error->second;
            std::cout << '\n';
        }
    } catch (const std::exception& error) {
        vm.record_bitmap_load_error(type, error.what());
    }
    return NativeSignal::Continue;
}
